CREATE TABLE IF NOT EXISTS governance_meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_number text NOT NULL UNIQUE, title text NOT NULL, governance_level text NOT NULL, meeting_date timestamptz, status text NOT NULL DEFAULT 'Scheduled', quorum_required integer NOT NULL DEFAULT 1, quorum_present integer NOT NULL DEFAULT 0, chair_name text, secretary_name text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES governance_meetings(id) ON DELETE CASCADE, person_name text NOT NULL, role_name text, attendance_status text NOT NULL DEFAULT 'Expected', conflict_declared boolean NOT NULL DEFAULT false, recused boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid REFERENCES governance_meetings(id) ON DELETE SET NULL, resolution_id uuid REFERENCES governance_resolutions(id) ON DELETE SET NULL, action_type text NOT NULL, action_title text NOT NULL, owner_name text, due_date date, status text NOT NULL DEFAULT 'Open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, entity_type text NOT NULL, entity_id uuid, actor_name text, event_summary text NOT NULL, event_hash text, previous_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gov_attendance_meeting ON governance_attendance(meeting_id);
CREATE INDEX IF NOT EXISTS idx_gov_actions_status ON governance_actions(status);
CREATE INDEX IF NOT EXISTS idx_gov_audit_created ON governance_audit_events(created_at DESC);